fn bg_of(a: i32) -> i32 {
    match a {
        0 => 0x102030,
        1 => 0x103018,
        _ => 0x2a1030,
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let tabw: i32 = w / 3;
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut active: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 && py < 40 {
        active = px / tabw;
        if active > 2 { active = 2; }
        host::display::state_set(0, active);
    }
    host::display::state_set(1, down);
    let bg: i32 = bg_of(active);
    host::display::clear(bg);
    let mut i: i32 = 0;
    while i < 3 {
        let c: i32 = if i == active { bg } else { 0x282828 };
        host::display::fill_rect(i * tabw, 0, tabw - 2, 40, c);
        if i == active {
            host::display::fill_rect(i * tabw, 0, tabw - 2, 3, 0xffffff);
        }
        i = i + 1;
    }
    host::display::draw_string(12, 16, "HOME", 0xffffff, 1);
    host::display::draw_string(tabw + 12, 16, "STATS", 0xffffff, 1);
    host::display::draw_string(tabw * 2 + 12, 16, "ABOUT", 0xffffff, 1);
    match active {
        0 => {
            host::display::draw_string(20, 80, "WELCOME HOME", 0xffffff, 2);
        }
        1 => {
            host::display::draw_string(20, 80, "FRAMES SO FAR", 0x88ff88, 2);
            host::display::draw_number(20, 110, t, 0xffffff, 2);
        }
        _ => {
            host::display::draw_string(20, 80, "ABOUT THIS APP", 0xcc88ff, 2);
        }
    }
    host::display::present();
}
